  const APPROVAL_LABELS={ot:'ทำงานล่วงเวลา (OT)',expense_transport:'เบิกค่ารถหรือค่าพาหนะ',expense_meal:'เบิกค่าอาหารและเครื่องดื่ม',expense_entertain:'เบิกค่า Entertain',expense_event:'เบิกค่า Event',expense_other:'เบิกค่าใช้จ่ายอื่น ๆ',time_adjust:'ปรับปรุงเวลาเข้า–ออก',shift_change:'เปลี่ยนกะทำงาน',offday_change:'เปลี่ยนกะวันหยุด',document:'ขอเอกสารบริษัท',special_earning:'ขอเงินได้พิเศษหรือรางวัล'};
