  function updateApprovalTypeFields(){const type=$("#approvalType").value,container=$("#approvalTypeFields"),details=$("#approvalDetails"),detailsLabel=$(".approval-details-label");container.innerHTML=approvalFieldMarkup(type)||"<p class=\"form-hint\">เลือกรายการเพื่อแสดงข้อมูลที่ต้องกรอก</p>";const optional=type==="offday_change";details.required=!!type&&!optional;details.placeholder=optional?"อธิบายเพิ่มเติมได้ถ้ามี (ไม่บังคับ)":"อธิบายเหตุผลหรือข้อมูลประกอบคำขอ";if(detailsLabel.firstChild)detailsLabel.firstChild.textContent=optional?"รายละเอียดเพิ่มเติม (ไม่บังคับ)":"รายละเอียดเพิ่มเติม";$("#approvalAttachments").required=type.startsWith("expense_")||type==="special_earning";$("#otApprovalNotice").hidden=type!=="ot";$("#specialEarningEstimate").hidden=type!=="special_earning";}function updateEarningEstimate(){const base=Number($('[name="earningBase"]')?.value)||0,rate=Number($('[name="earningRate"]')?.value)||0;$('#specialEarningEstimateValue').textContent=new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB'}).format(base*rate/100);}
  function readRequestAttachments(files){const list=[...files];if(list.length>3)throw new Error('แนบไฟล์ได้สูงสุด 3 ไฟล์');const allowed=['application/pdf','image/png','image/jpeg','image/webp'];if(list.some(f=>!allowed.includes(f.type)))throw new Error('รองรับเฉพาะ PDF, PNG, JPG และ WEBP');if(list.reduce((n,f)=>n+f.size,0)>2*1024*1024)throw new Error('ขนาดไฟล์รวมต้องไม่เกิน 2 MB');return Promise.all(list.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result});reader.onerror=()=>reject(new Error('อ่านไฟล์แนบไม่สำเร็จ'));reader.readAsDataURL(file);})));}
  function approvalAttachmentsMarkup(files){return (files||[]).map(a=>{if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(a.type)||!String(a.data||'').startsWith(`data:${a.type};base64,`))return '';return `<a class="approval-file-link" href="${a.data}" target="_blank" rel="noopener noreferrer">${escapeHTML(a.name||'ไฟล์แนบ')} ↗</a>`;}).filter(Boolean).join(' ' )||'—';}
