  function approvalFieldsMarkup(fields){const names={date:'วันที่',startTime:'เริ่ม OT',endTime:'สิ้นสุด OT',amount:'จำนวนเงิน',expenseDescription:'รายการ',customExpenseType:'ประเภทอื่น',requestedCheckIn:'เวลาเข้าใหม่',requestedCheckOut:'เวลาออกใหม่',effectiveMonth:'เดือนเริ่มมีผล',requestedShift:'กะที่ขอ',offDayOne:'วันหยุด 1',offDayTwo:'วันหยุด 2',documentType:'เอกสาร',documentCopies:'จำนวนฉบับ',neededBy:'วันที่ต้องการ',earningType:'ประเภทรายได้',earningBase:'ฐานคำนวณ',earningRate:'อัตรา (%)',calculatedAmount:'ยอดคำนวณ (บาท)'};return Object.entries(fields||{}).map(([k,v])=>`${escapeHTML(names[k]||k)}: ${escapeHTML(k==='offDayOne'||k==='offDayTwo'?APPROVAL_DAYS[Number(v)]||v:v)}`).join(' · ')||'—';}
