  function submitApprovalRequest(ev){ev.preventDefault();const type=$('#approvalType').value,e=employee(activeUserId),container=$('#approvalTypeFields');if(!type||!e||e.status!=='active'){showToast('กรุณาเลือกประเภทคำขอและเข้าสู่ระบบด้วยบัญชีพนักงาน',true);return;}const fields={};$$('[name]',container).forEach(input=>{fields[input.name]=input.value;});if(type==='ot'&&fields.endTime<=fields.startTime){showToast('เวลาสิ้นสุด OT ต้องอยู่หลังเวลาเริ่ม',true);return;}if(type==='ot'&&fields.date<todayISO()){showToast('คำขอ OT ต้องยื่นก่อนถึงวันที่ทำงานล่วงเวลา',true);return;}if(type==='time_adjust'&&!fields.requestedCheckIn&&!fields.requestedCheckOut){showToast('กรุณาระบุเวลาเข้าใหม่หรือเวลาออกใหม่อย่างน้อยหนึ่งรายการ',true);return;}if(type==='offday_change'&&fields.offDayOne===fields.offDayTwo){showToast('วันหยุดสองวันต้องไม่ซ้ำกัน',true);return;}if(type==='special_earning')fields.calculatedAmount=(Number(fields.earningBase)*Number(fields.earningRate)/100).toFixed(2);if(['shift_change','offday_change'].includes(type)&&approvalRequests.some(x=>x.employeeId===e.id&&x.type===type&&x.fields?.effectiveMonth===fields.effectiveMonth&&x.status!=='ไม่อนุมัติ')){showToast('คำขอประเภทนี้ของเดือนดังกล่าวมีแล้ว จำกัดเดือนละ 1 ครั้ง',true);return;}readRequestAttachments($('#approvalAttachments').files).then(attachments=>{const request={id:crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,type,employeeId:e.id,employeeCode:e.code,employeeName:e.name,department:e.department,fields,details:$('#approvalDetails').value.trim(),attachments,status:'รออนุมัติ',createdAt:new Date().toISOString()};approvalRequests.push(request);if(!saveAll()){approvalRequests.pop();return;}$('#approvalRequestForm').reset();updateApprovalTypeFields();renderApprovalRequests();renderEmployeeDashboard();showToast('ส่งคำขอแล้ว รอผู้อนุมัติและ HR ตรวจสอบ');}).catch(error=>showToast(error.message||'อ่านไฟล์แนบไม่สำเร็จ',true));}
