  function reviewApprovalRequest(id,approved,reason=''){if(!isHRSession())return;const request=approvalRequests.find(x=>x.id===id);if(!request||request.status!=='รออนุมัติ')return;if(!approved&&!reason.trim()){showToast('กรุณาระบุเหตุผลที่ไม่อนุมัติ',true);return;}request.status=approved?'อนุมัติ':'ไม่อนุมัติ';request.reviewedAt=new Date().toISOString();request.reviewedBy=employee(activeUserId)?.name||'HR';request.reviewReason=approved?'':reason.trim();if(!saveAll())return;renderApprovalRequests();renderEmployeeDashboard();showToast(approved?'อนุมัติคำขอแล้ว':'บันทึกผลไม่อนุมัติแล้ว');}
function payrollCurrency(value){return new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB'}).format(Number(value)||0);}
