function announcementStatusLabel(item,now=new Date()){if(item.status!=='published')return 'ร่าง';const start=dateTime(item.displayStart),end=dateTime(item.displayEnd);if(!start||!end)return 'กำหนดเวลาไม่ถูกต้อง';if(now<start)return 'ตั้งเวลาเผยแพร่';if(now>end)return 'หมดเวลาแสดง';return 'กำลังแสดง';}
