  function announcementRelatedPeriod(item){const start=item.relatedStart||'',end=item.relatedEnd||'',startTime=item.relatedStartTime||'',endTime=item.relatedEndTime||'';if(!start&&!end&&!startTime&&!endTime)return '—';const dates=!start&&!end?'':start&&end&&start===end?announcementDateText(start):start&&end?`${announcementDateText(start)} – ${announcementDateText(end)}`:announcementDateText(start||end),times=startTime&&endTime?`เวลา ${startTime}–${endTime} น.`:startTime?`เริ่มเวลา ${startTime} น.`:endTime?`สิ้นสุดเวลา ${endTime} น.`:'';return [dates,times].filter(Boolean).join(' · ');}
